(()=>{window.__qaEmpty=null;const END=Date.now()+90000;const tick=async()=>{try{const r=await (async()=>{const h=await import('/src/studio/assistant/chatHistory.ts');const a=await h.readChatArchive(window.__qaJob);
const t=a?.threads.find(x=>x.id===a.activeId);
